class RomanNumeralConverter:
    def __init__(self):
        self.typical_numerals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
        self.subtractive_combinations = {'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90, 'CD': 400, 'CM': 900}

    def roman_to_int(self, s: str) -> int:
        total = 0
        i = 0
        while i < len(s):
            if i+1 < len(s) and s[i:i+2] in self.subtractive_combinations:
                total += self.subtractive_combinations[s[i:i+2]]
                i += 2
            else:
                total += self.typical_numerals[s[i]]
                i += 1
        return total

# Test the program with various input cases
converter = RomanNumeralConverter()
print(converter.roman_to_int("III"))  # Output: 3
print(converter.roman_to_int("IV"))   # Output: 4
print(converter.roman_to_int("IX"))   # Output: 9
print(converter.roman_to_int("LVIII"))  # Output: 58
print(converter.roman_to_int("MCMXCIV"))  # Output: 1994

